create table wksp_dtesc.sgt_ot_notificacion (
    id              number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache
    20 noorder nocycle nokeep noscale not null enable,
    ot_id           number not null enable,
    usuario_destino varchar2(255 byte) not null enable,
    tipo            varchar2(30 byte) not null enable,
    mensaje         varchar2(1000 byte) not null enable,
    leida           char(1 byte) default 'N' not null enable,
    fecha_creacion  timestamp(6) default systimestamp not null enable,
    fecha_lectura   timestamp(6)
);

alter table wksp_dtesc.sgt_ot_notificacion
    add constraint chk_sgt_ot_noti_leida
        check ( leida in ( 'Y', 'N' ) ) enable;

alter table wksp_dtesc.sgt_ot_notificacion
    add constraint chk_sgt_ot_noti_tipo
        check ( tipo in ( 'ASIGNACION', 'REASIGNACION', 'CAMBIO_ESTADO', 'GENERAL' ) ) enable;

alter table wksp_dtesc.sgt_ot_notificacion add primary key ( id )
    using index enable;


